import math
import re

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if start is None: start = 0.0
    if horizon is None: horizon = 127.0

    scope_node = node_by_title(doc, scope)
    motion_node = None
    for child in children(doc, scope_node):
        if "Motion log" in child.get("title", ""):
            motion_node = child
            break

    obj_history = {}
    if motion_node:
        rows = table_rows(motion_node)
        for ridx, rdata in rows:
            obj_str = rdata.get("object", "")
            m_obj = re.match(r"(\d+)", obj_str)
            if m_obj:
                oid = f"Object {m_obj.group(1)}"
                if oid not in obj_history: obj_history[oid] = []
                obj_history[oid].append({
                    "frame": int(float(rdata["frame"])),
                    "x": float(rdata["x"]), "y": float(rdata["y"]),
                    "vx": float(rdata["vx"]), "vy": float(rdata["vy"])
                })
    for k in obj_history: obj_history[k].sort(key=lambda r: r["frame"])

    objects = {}
    for inp in inputs:
        oid = inp["entities"][0]
        fields = inp["fields"]
        objects[oid] = {
            "id": oid,
            "entry": inp["time"],
            "x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0
        }

    SCALE = 1.0/36.0
    for oid, obj in objects.items():
        fields = next((i["fields"] for i in inputs if i["entities"][0] == oid), {})
        if oid in obj_history:
            hist = obj_history[oid]
            best = prev = None
            for rec in hist:
                if rec["frame"] <= start:
                    prev = best
                    best = rec
                else: break
            if best:
                obj["x"] = best["x"]
                obj["y"] = best["y"]
                if prev:
                    dt = best["frame"] - prev["frame"]
                    obj["vx"] = (best["x"] - prev["x"]) / dt if dt > 0 else best["vx"] * SCALE
                    obj["vy"] = (best["y"] - prev["y"]) / dt if dt > 0 else best["vy"] * SCALE
                else:
                    obj["vx"] = best["vx"] * SCALE
                    obj["vy"] = best["vy"] * SCALE
                dt_extra = start - best["frame"]
                if dt_extra > 0:
                    obj["x"] += obj["vx"] * dt_extra
                    obj["y"] += obj["vy"] * dt_extra
                    obj["vx"] *= 0.99**dt_extra
                    obj["vy"] *= 0.99**dt_extra
            else:
                obj["x"] = fields.get("x", 0.0)
                obj["y"] = fields.get("y", 0.0)
                obj["vx"] = fields.get("vx", 0.0) * SCALE
                obj["vy"] = fields.get("vy", 0.0) * SCALE
                dt_extra = start - obj["entry"]
                if dt_extra > 0:
                    obj["x"] += obj["vx"] * dt_extra
                    obj["y"] += obj["vy"] * dt_extra
                    obj["vx"] *= 0.99**dt_extra
                    obj["vy"] *= 0.99**dt_extra
        else:
            obj["x"] = fields.get("x", 0.0)
            obj["y"] = fields.get("y", 0.0)
            obj["vx"] = fields.get("vx", 0.0) * SCALE
            obj["vy"] = fields.get("vy", 0.0) * SCALE
            dt_extra = start - obj["entry"]
            if dt_extra > 0:
                obj["x"] += obj["vx"] * dt_extra
                obj["y"] += obj["vy"] * dt_extra
                obj["vx"] *= 0.99**dt_extra
                obj["vy"] *= 0.99**dt_extra

    outcomes = []
    obj_list = list(objects.values())
    collided_pairs = set()

    t = start
    dt_step = 0.5
    while t < horizon:
        for obj in obj_list:
            if obj["entry"] > t: continue
            s = math.hypot(obj["vx"], obj["vy"])
            if s > 0.01:
                obj["vx"] *= 0.995
                obj["vy"] *= 0.995
            else:
                obj["vx"] = 0.0
                obj["vy"] = 0.0
            obj["x"] += obj["vx"] * dt_step
            obj["y"] += obj["vy"] * dt_step

        for i in range(len(obj_list)):
            for j in range(i+1, len(obj_list)):
                o1 = obj_list[i]
                o2 = obj_list[j]
                if o1["entry"] > t or o2["entry"] > t: continue
                dx = o2["x"] - o1["x"]
                dy = o2["y"] - o1["y"]
                dist = math.hypot(dx, dy)
                pair = tuple(sorted([o1["id"], o2["id"]]))
                if dist > 0.5:
                    collided_pairs.discard(pair)
                elif dist <= 0.41 and dist > 0.01:
                    if pair not in collided_pairs:
                        collided_pairs.add(pair)
                        outcomes.append({
                            "time": round(t, 1),
                            "kind": "collision",
                            "entities": list(pair),
                            "value": None,
                            "src": []
                        })
                        nx, ny = dx/dist, dy/dist
                        dvx = o1["vx"] - o2["vx"]
                        dvy = o1["vy"] - o2["vy"]
                        dvn = dvx*nx + dvy*ny
                        if dvn > 0:
                            o1["vx"] -= dvn * nx
                            o1["vy"] -= dvn * ny
                            o2["vx"] += dvn * nx
                            o2["vy"] += dvn * ny
                            overlap = 0.41 - dist
                            o1["x"] -= overlap * nx
                            o1["y"] -= overlap * ny
                            o2["x"] += overlap * nx
                            o2["y"] += overlap * ny
        t += dt_step
    return outcomes
